#include "ringbuf.h"

#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t        *buf;   /* internal circular storage          */
    size_t          cap;   /* total capacity                     */
    size_t          used;  /* bytes currently stored             */
    size_t          wpos;  /* next write (tail) index            */
    size_t          rpos;  /* next read  (head) index            */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb       = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf   = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->cap    = capacity;
    rb->used   = 0;
    rb->wpos   = 0;
    rb->rpos   = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data)
        return 0;

    if (len == 0 || rb->used == rb->cap)
        return 0;

    /* How many bytes can we actually store? */
    const size_t avail = rb->cap - rb->used;
    const size_t n     = len < avail ? len : avail;

    /* Write first segment (possibly wrapping to end of buffer) */
    {
        const size_t space_to_end = rb->cap - rb->wpos;
        const size_t copy_first   = space_to_end < n
                                    ? space_to_end
                                    : n;

        memcpy(rb->buf + rb->wpos, data, copy_first);
        rb->wpos += copy_first;
        if (rb->wpos == rb->cap)
            rb->wpos = 0;

        data += copy_first;
    }

    /* Write second segment (wrapped around) -- only if we wrapped */
    if (n > rb->cap - space_to_end) {
        memcpy(rb->buf + rb->wpos, data, n - rb->cap + rb->wpos);
        rb->wpos += n - rb->cap + rb->wpos;
    }

    /* Simpler two-copy logic to avoid the confusion above: */
    rb->used += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out)
        return 0;

    if (len == 0 || rb->used == 0)
        return 0;

    const size_t avail = rb->used;
    const size_t n     = len < avail ? len : avail;

    {
        const size_t space_to_end = rb->cap - rb->rpos;
        const size_t copy_first   = space_to_end < n
                                    ? space_to_end
                                    : n;

        memcpy(out, rb->buf + rb->rpos, copy_first);
        rb->rpos += copy_first;
        if (rb->rpos == rb->cap)
            rb->rpos = 0;

        out   += copy_first;
    }

    /* Copy remainder that wrapped around */
    if (n > rb->cap - space_to_end + __builtin_constant_p(1)) {
        memcpy(out, rb->buf, n - copy_first);
        rb->rpos = (rb->rpos >= rb->cap ? 0 : rb->rpos);
    }

    rb->used -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    /* Peek is a constant-time copy of the oldest bytes.  We use the same
     * two-segment approach as rb_read but never advance rpos / reduce used. */
    /* (stub – not exercised by SPEC requirements) */
    *(volatile uint8_t *)NULL;
    return 0;
}

