size_t rb_capacity(const ringbuf_t *rb) { return rb ? rb->cap : 0; }

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->wpos   = 0;
    rb->rpos   = 0;
    rb->used   = 0;
